func (c *Controller) handleSession(ctx context.Context, req request) (payload any, resultErr error) {
	stage := "decode"
	defer func() {
		if resultErr != nil {
			c.logSessionFailure(stage, resultErr)
		}
	}()
	var operation struct {
		Kind string `json:"kind"`
	}
	if err := decodeStrict(req.Payload, &operation); err != nil {
		return nil, err
	}
	stateKey := sessionKey(c.cell, req.Node)
	for attempt := range 8 {
		stage = "registration"
		r, err := c.registration(ctx, req.Node)
		if err != nil {
			return nil, err
		}
		key, err := decodePublicKey(r.PublicKey)
		if err != nil {
			return nil, err
		}
		stage = "verify"
		if err := verifyRequest(req, key, c.cell, time.Now().UTC()); err != nil {
			return nil, err
		}
		if err := c.verifyCredentialProtocol(ctx, req, r); err != nil {
			return nil, err
		}
		now := time.Now().UTC()
		stage = "session_read"
		old, revision, exists, err := c.sessionSnapshot(ctx, stateKey)
		if err != nil {
			return nil, err
		}
		if exists && exactSessionReplay(old, r, req, operation.Kind, now) {
			stage = "session_write"
			if _, err := c.cas(ctx, stateKey, old, revision); err == nil {
				return old, nil
			} else if casConflict(err) {
				if err := waitSessionConflict(ctx, attempt); err != nil {
					return nil, err
				}
				continue
			} else {
				return nil, err
			}
		}
		var next session
		stage = "session_validate"
		switch operation.Kind {
		case "acquire":
			if req.Epoch != 0 {
				return nil, errors.New("acquire requires epoch zero")
			}
			if exists && sessionHeld(old, r, now) {
				return nil, errSessionOwned
			}
			next = session{RegistrationGeneration: r.Generation, SessionID: req.SessionID, Epoch: 1, ExpiresAt: req.IssuedAt.Add(sessionTTL), LastNonce: req.Nonce, LastIssuedAt: req.IssuedAt}
			if exists {
				if old.Epoch == ^uint64(0) {
					return nil, errors.New("session epoch exhausted")
				}
				next.Epoch = old.Epoch + 1
			}
		case "renew":
			if !exists || !renewableSession(old, r, req, now) {
				return nil, errors.New("session is no longer renewable")
			}
			next = old
			next.ExpiresAt = req.IssuedAt.Add(sessionTTL)
			next.LastNonce = req.Nonce
			next.LastIssuedAt = req.IssuedAt
		default:
			return nil, errors.New("unknown session operation")
		}
		stage = "session_write"
		written, err := c.cas(ctx, stateKey, next, revision)
		if err == nil && written > 0 {
			return next, nil
		}
		if !casConflict(err) {
			return nil, err
		}
		if err := waitSessionConflict(ctx, attempt); err != nil {
			return nil, err
		}
	}
	stage = "registration"
	r, err := c.registration(ctx, req.Node)
	if err != nil {
		return nil, err
	}
	key, err := decodePublicKey(r.PublicKey)
	if err != nil {
		return nil, err
	}
	stage = "verify"
	if err := verifyRequest(req, key, c.cell, time.Now().UTC()); err != nil {
		return nil, err
	}
	stage = "session_read"
	old, revision, exists, err := c.sessionSnapshot(ctx, stateKey)
	if err != nil {
		return nil, err
	}
	now := time.Now().UTC()
	if exists && exactSessionReplay(old, r, req, operation.Kind, now) {
		stage = "session_write"
		if _, err := c.cas(ctx, stateKey, old, revision); err == nil {
			return old, nil
		} else if !casConflict(err) {
			return nil, err
		}
		return nil, errSessionContention
	}
	stage = "session_validate"
	switch operation.Kind {
	case "acquire":
		if req.Epoch != 0 {
			return nil, errors.New("acquire requires epoch zero")
		}
		if exists && sessionHeld(old, r, now) {
			return nil, errSessionOwned
		}
	case "renew":
		if !exists || !renewableSession(old, r, req, now) {
			return nil, errors.New("session is no longer renewable")
		}
	default:
		return nil, errors.New("unknown session operation")
	}
	return nil, errSessionContention
}

authorize.text:
func renewableSession(old session, r Registration, req request, now time.Time) bool {
	return old.RegistrationGeneration == r.Generation && old.SessionID == req.SessionID && old.Epoch == req.Epoch &&
		now.Before(old.ExpiresAt) && req.IssuedAt.After(old.LastIssuedAt)
}

func currentAuthorizedSession(s session, r Registration, req request, now time.Time) bool {
	return s.RegistrationGeneration == r.Generation && s.SessionID == req.SessionID && s.Epoch == req.Epoch &&
		now.Before(s.ExpiresAt) && !req.IssuedAt.Before(s.LastIssuedAt.Add(-requestTTL))
}

func (c *Controller) authorize(ctx context.Context, req request) (Registration, session, error) {
	stateKey := sessionKey(c.cell, req.Node)
	for attempt := range 8 {
		r, err := c.registration(ctx, req.Node)
		if err != nil {
			return Registration{}, session{}, err
		}
		key, err := decodePublicKey(r.PublicKey)
		if err != nil {
			return Registration{}, session{}, err
		}
		if err := verifyRequest(req, key, c.cell, time.Now().UTC()); err != nil {
			return Registration{}, session{}, err
		}
		if err := c.verifyCredentialProtocol(ctx, req, r); err != nil {
			return Registration{}, session{}, err
		}
		s, revision, exists, err := c.sessionSnapshot(ctx, stateKey)
		if err != nil {
			return Registration{}, session{}, err
		}
		if !exists || !currentAuthorizedSession(s, r, req, time.Now()) {
			return Registration{}, session{}, errors.New("host session is not current")
		}
		if _, err := c.cas(ctx, stateKey, s, revision); err == nil {
			return r, s, nil
		} else if !casConflict(err) {
			return Registration{}, session{}, fmt.Errorf("host session changed: %w", err)
		}
		if err := waitSessionConflict(ctx, attempt); err != nil {
			return Registration{}, session{}, err
		}
	}
	r, err := c.registration(ctx, req.Node)
	if err != nil {
		return Registration{}, session{}, err
	}
	key, err := decodePublicKey(r.PublicKey)
	if err != nil {
		return Registration{}, session{}, err
	}
	if err := verifyRequest(req, key, c.cell, time.Now().UTC()); err != nil {
		return Registration{}, session{}, err
	}
	if err := c.verifyCredentialProtocol(ctx, req, r); err != nil {
		return Registration{}, session{}, err
	}
	s, _, exists, err := c.sessionSnapshot(ctx, stateKey)
	if err != nil {
		return Registration{}, session{}, err
	}
	if !exists || !currentAuthorizedSession(s, r, req, time.Now()) {
		return Registration{}, session{}, errors.New("host session is not current")
	}
	return Registration{}, session{}, errSessionContention
}

dispatch.text:
func (c *Controller) handleAuthorized(ctx context.Context, req request) (payload any, resultErr error) {
	r, s, err := c.authorize(ctx, req)
	if err != nil {
		return nil, err
	}
	epoch := c.authorityEpoch()
	if err := c.guard(ctx, epoch); err != nil {
		return nil, err
	}
	requireActive := req.Operation == "material" || req.Operation == "container-material" || req.Operation == "registry-admission" || req.Operation == "function-material"
	if req.Operation == "runtime-effect" {
		var operation struct {
			Action string `json:"action"`
		}
		if err := json.Unmarshal(req.Payload, &operation); err != nil {
			return nil, err
		}
		requireActive = operation.Action != "close"
	}
	defer func() {
		if resultErr != nil {
			return
		}
		if err := c.recheckReplyAuthority(ctx, epoch, req, r, requireActive); err != nil {
			payload, resultErr = nil, err
		}
	}()
	switch req.Operation {
	case "desired":
		registration, registrationRevision, exists, err := c.readRegistration(ctx, req.Node)
		if err != nil {
			return nil, err
		}
		if !exists || !sameJSON(registration, r) || registration.Generation != s.RegistrationGeneration {
			return nil, errors.New("host registration changed during desired request")
		}
		var query struct {
			Role string `json:"role"`
		}
		if err := decodeStrict(req.Payload, &query); err != nil {
			return nil, err
		}
		if !slices.Contains(r.Roles, query.Role) {
			return nil, errors.New("role is not registered")
		}
		desired, revision, exists, err := c.readDesired(ctx, req.Node, query.Role)
		if err != nil {
			return nil, err
		}
		if !exists {
			return desiredReply{Registration: &registration, RegistrationRevision: registrationRevision}, nil
		}
		return desiredReply{Desired: &desired, Revision: revision, Registration: &registration, RegistrationRevision: registrationRevision}, nil
	case "artifact":
		return c.serveArtifact(ctx, req, r)
	case "material":
		return c.serveMaterial(ctx, req, r, s)
	case "function-material":
		return c.serveFunctionMaterial(ctx, req, r, s)
	case "volume-init":
		return c.serveVolumeInit(ctx, req, r, s)
	case "runtime-effect":
		return c.serveRuntimeEffect(ctx, req, r, s)
	case "container-material":
		return c.serveContainerMaterial(ctx, req, r, s)
	case "registry-admission":
		return c.serveRegistryAdmission(ctx, req, r, s)
	case "drain-command":
		return c.serveManagedDrainCommand(ctx, req, r)
	case "drain-result":
		return c.storeManagedDrainResult(ctx, req, r)
	case "backup-command":
		return c.serveManagedBackupCommand(ctx, req, r)
	case "backup-result":
		return c.storeManagedBackupResult(ctx, req, r)
	case "cycle":
		return c.serveCycle(ctx, req, r, s)
	case "report":
		return c.storeReport(ctx, req, r, s)
	case "load":
		return c.storeLoad(ctx, req, r)
	case "rollout", "rollout-binary":
		return c.serveRollout(ctx, req, r)
	case "netbird", "netbird-binary":
		return c.serveNetBird(ctx, req, r)
	case "terrabase-peer":
		return c.serveTerraBasePeer(ctx, req, r)
	case "terrabase-format":
		return c.serveTerraBaseFormat(ctx, req, r)
	case "role-identity":
		return c.serveRoleIdentity(ctx, req, r)
	}
	return nil, errors.New("unknown host operation")
}

mutation_reads.text:
func (c *Controller) readRegistration(ctx context.Context, node string) (Registration, uint64, bool, error) {
	if err := validateToken(node, "node"); err != nil {
		return Registration{}, 0, false, err
	}
	key := registrationSubjectKey(c.cell, node)
	entry, err := c.mutations.ReadHostMutation(ctx, authority.MutationRegistration, key)
	if errors.Is(err, authority.ErrNotFound) {
		return Registration{}, 0, false, nil
	}
	if err != nil {
		return Registration{}, 0, false, err
	}
	if entry.Kind != authority.MutationRegistration || entry.SubjectKey != key || entry.Sequence == 0 || entry.Epoch == 0 {
		return Registration{}, 0, false, errors.New("registration log entry is malformed")
	}
	var r Registration
	if err := decodeStrict(entry.Payload, &r); err != nil {
		return Registration{}, 0, false, err
	}
	if r.Node != node || r.ID != entityid.Derive("host", c.cell, node) {
		return Registration{}, 0, false, errors.New("registration log identity mismatch")
	}
	if err := validateRegistration(r, c.cell); err != nil {
		return Registration{}, 0, false, err
	}
	return r, entry.Sequence, true, nil
}

func (c *Controller) readDesired(ctx context.Context, node, role string) (Desired, uint64, bool, error) {
	if err := validateToken(node, "node"); err != nil {
		return Desired{}, 0, false, err
	}
	if err := validateToken(role, "role"); err != nil {
		return Desired{}, 0, false, err
	}
	key := desiredSubjectKey(c.cell, node, role)
	entry, err := c.mutations.ReadHostMutation(ctx, authority.MutationDesired, key)
	if errors.Is(err, authority.ErrNotFound) {
		return Desired{}, 0, false, nil
	}
	if err != nil {
		return Desired{}, 0, false, err
	}
	if entry.Kind != authority.MutationDesired || entry.SubjectKey != key || entry.Sequence == 0 || entry.Epoch == 0 {
		return Desired{}, 0, false, errors.New("desired log entry is malformed")
	}
	var d Desired
	if err := decodeStrict(entry.Payload, &d); err != nil {
		return Desired{}, 0, false, err
	}
	if d.Cell != c.cell || d.Node != node || d.Role != role || d.AuthorityEpoch != entry.Epoch {
		return Desired{}, 0, false, errors.New("desired log identity or epoch mismatch")
	}
	return d, entry.Sequence, true, nil
}

reply_authority.text:
func (c *Controller) recheckReplyAuthority(ctx context.Context, epoch uint64, req request, registration Registration, requireActive bool) error {
	latest, err := c.registration(ctx, req.Node)
	if err != nil || !sameJSON(registration, latest) {
		return errors.New("host registration changed while handling request")
	}
	key, err := decodePublicKey(latest.PublicKey)
	if err != nil || verifyRequest(req, key, c.cell, time.Now().UTC()) != nil {
		return errors.New("host request expired while handling request")
	}
	active, _, exists, err := c.sessionSnapshot(ctx, sessionKey(c.cell, req.Node))
	if err != nil {
		return err
	}
	if !exists || !currentAuthorizedSession(active, latest, req, time.Now()) {
		return errors.New("host session changed while handling request")
	}
	if requireActive {
		retired, err := c.retired(ctx, req.Node)
		if err != nil {
			return err
		}
		if retired {
			return errors.New("retired host cannot receive current material or runtime authority")
		}
	}
	if err := c.verifyCredentialProtocol(ctx, req, latest); err != nil {
		return err
	}
	return c.guard(ctx, epoch)
}

reader.text:
func NewReader(ctx context.Context, cfg ReaderConfig) (*Reader, error) {
	if err := validateToken(cfg.Cell, "cell"); err != nil {
		return nil, err
	}
	if cfg.HostMutations == nil || cfg.Conn == nil {
		return nil, errors.New("reader requires NATS connection and ordered host mutation store")
	}
	state := cfg.State
	if state == nil {
		if cfg.JS == nil {
			return nil, errors.New("reader requires JetStream or host state")
		}
		var err error
		state, err = cfg.JS.KeyValue(ctx, stateBucket)
		if err != nil {
			return nil, err
		}
	}
	replicas := cfg.StateReplicas
	if replicas == 0 {
		replicas = 3
	}
	status, err := state.Status(ctx)
	if err != nil {
		return nil, err
	}
	if status.Config().Replicas != replicas {
		return nil, fmt.Errorf("host state has %d replicas, requires %d", status.Config().Replicas, replicas)
	}
	controlLog := cfg.ControlLog
	if controlLog == nil {
		if cfg.JS == nil {
			return nil, errors.New("reader requires JetStream or control log")
		}
		controlLog, err = cfg.JS.Stream(ctx, "TS_CONTROL_LOG")
		if err != nil {
			return nil, err
		}
	}
	return &Reader{controller: &Controller{cell: cfg.Cell, conn: cfg.Conn, state: state, controlLog: controlLog, mutations: cfg.HostMutations, credentialFloor: cfg.ManagedCredentialFloor, readOnly: true}}, nil
}

function_material.text:
func validateFunctionMaterialBinding(binding FunctionMaterialBinding) error {
	return (authority.FunctionBinding{TaskID: binding.TaskID, ServiceID: binding.ServiceID, NodeID: binding.NodeID,
		InstanceID: binding.InstanceID, Region: binding.Region, HostID: binding.HostID, Fingerprint: binding.Fingerprint,
		MaterialManifestSHA256: binding.Fingerprint}).Validate()
}

func functionMaterialLimit(name string) int {
	switch name {
	case "module.wasm":
		return release.MaxFunctionModuleBytes
	case "root.pub":
		return 32
	case "deployment.json":
		return 16 << 10
	default:
		return 64 << 10
	}
}

func functionMaterialChunkSize(name string) int {
	if name == "module.wasm" {
		return artifactChunkBytes
	}
	return materialChunkBytes
}

func functionMaterialDigest(files map[string][]byte, expires, credentialExpires time.Time) (string, error) {
	if len(files) != len(functionMaterialNames) || !time.Now().Before(expires) || !time.Now().Before(credentialExpires) || expires.After(credentialExpires) {
		return "", errors.New("function material inventory is incomplete or expired")
	}
	type fileDigest struct {
		Name   string `json:"name"`
		Bytes  int    `json:"bytes"`
		SHA256 string `json:"sha256"`
	}
	inventory := make([]fileDigest, 0, len(files))
	for _, name := range functionMaterialNames {
		content := files[name]
		if len(content) == 0 || len(content) > functionMaterialLimit(name) {
			return "", errors.New("function material file is missing or oversized")
		}
		digest := sha256.Sum256(content)
		inventory = append(inventory, fileDigest{Name: name, Bytes: len(content), SHA256: hex.EncodeToString(digest[:])})
	}
	wire, err := protocol.EncodeJSON(struct {
		Files               []fileDigest `json:"files"`
		ExpiresAt           time.Time    `json:"expires_at"`
		CredentialExpiresAt time.Time    `json:"credential_expires_at"`
	}{inventory, expires, credentialExpires})
	if err != nil {
		return "", err
	}
	digest := sha256.Sum256(wire)
	return hex.EncodeToString(digest[:]), nil
}

func (c *Controller) serveFunctionMaterial(ctx context.Context, req request, registration Registration, currentSession session) (any, error) {
	if c.functionMaterial == nil || c.authorityEpoch == nil || registration.Generation != currentSession.RegistrationGeneration ||
		registration.Node != req.Node || !slices.Contains(registration.Roles, "function-worker") {
		return nil, errors.New("function material delivery is unavailable for this host")
	}
	var query functionMaterialQuery
	if err := decodeStrict(req.Payload, &query); err != nil {
		return nil, err
	}
	region, known := catalog.CellForOCIRegion(query.Binding.Region)
	if validateFunctionMaterialBinding(query.Binding) != nil || !known || region.Name() != c.cell ||
		query.Binding.HostID != registration.ID || query.RegistrationGeneration != registration.Generation ||
		!slices.Contains(functionMaterialNames[:], query.File) || query.Offset < 0 ||
		query.Offset >= functionMaterialLimit(query.File) || query.Length < 1 || query.Length > functionMaterialChunkSize(query.File) ||
		len(query.EphemeralPublicKey) != 32 {
		return nil, errors.New("function material query differs from the registered host or file bounds")
	}
	epoch := c.authorityEpoch()
	if err := c.guard(ctx, epoch); err != nil {
		return nil, err
	}
	material, err := c.functionMaterial(ctx, registration, query.Binding)
	if err != nil {
		return nil, err
	}
	defer func() {
		for _, content := range material.Files {
			clear(content)
		}
	}()
	manifest, err := functionMaterialDigest(material.Files, material.ExpiresAt, material.CredentialExpiresAt)
	if err != nil {
		return nil, err
	}
	contents := material.Files[query.File]
	if query.Offset >= len(contents) {
		return nil, errors.New("function material chunk starts past the file")
	}
	latest, err := c.registration(ctx, req.Node)
	if err != nil || !sameJSON(registration, latest) {
		return nil, errors.New("function material host registration changed")
	}
	session, _, exists, err := c.sessionSnapshot(ctx, sessionKey(c.cell, req.Node))
	if err != nil {
		return nil, err
	}
	if !exists || !currentAuthorizedSession(session, latest, req, time.Now()) || !time.Now().Before(material.ExpiresAt) {
		return nil, errors.New("function material session or delivery expired")
	}
	if err := c.guard(ctx, epoch); err != nil {
		return nil, err
	}
	aad, err := materialAAD(req, query)
	if err != nil {
		return nil, err
	}
	end := min(len(contents), query.Offset+query.Length)
	chunk, err := encryptHostMaterialChunk(aad, query.EphemeralPublicKey, query.File, query.Offset,
		contents[query.Offset:end], len(contents), contents)
	if err != nil {
		return nil, err
	}
	return functionMaterialReply{materialReply: chunk, ExpiresAt: material.ExpiresAt, CredentialExpiresAt: material.CredentialExpiresAt, ManifestSHA256: manifest}, nil
}

// CurrentFunctionFiles retains the file-only caller API.
func (a *Agent) CurrentFunctionFiles(ctx context.Context, binding FunctionMaterialBinding) (map[string][]byte, time.Time, error) {
	material, err := a.CurrentFunctionMaterial(ctx, binding)
	return material.Files, material.ExpiresAt, err
}

// CurrentFunctionMaterial retrieves an exact task inventory and its verified
// credential lifetime over the existing signed, encrypted host session.
func (a *Agent) CurrentFunctionMaterial(ctx context.Context, binding FunctionMaterialBinding) (result FunctionMaterialFiles, resultErr error) {
	if err := validateFunctionMaterialBinding(binding); err != nil {
		return FunctionMaterialFiles{}, err
	}
	if a.sessionLost.Load() {
		return FunctionMaterialFiles{}, errors.New("host session was lost")
	}
	session, _, err := a.executionLease()
	if err != nil {
		return FunctionMaterialFiles{}, err
	}
	files := make(map[string][]byte, len(functionMaterialNames))
	defer func() {
		if resultErr != nil {
			for _, content := range files {
				clear(content)
			}
		}
	}()
	manifest := ""
	var expires, credentialExpires time.Time
	for _, name := range functionMaterialNames {
		content, currentManifest, currentExpiry, currentCredentialExpiry, err := a.downloadFunctionFile(ctx, binding, session.RegistrationGeneration, name, manifest, expires, credentialExpires)
		if err != nil {
			return FunctionMaterialFiles{}, fmt.Errorf("retrieve function material %s: %w", name, err)
		}
		files[name], manifest, expires, credentialExpires = content, currentManifest, currentExpiry, currentCredentialExpiry
	}
	actual, err := functionMaterialDigest(files, expires, credentialExpires)
	if err != nil || actual != manifest {
		return FunctionMaterialFiles{}, errors.New("function material inventory changed during delivery")
	}
	if _, _, err := a.executionLease(); err != nil {
		return FunctionMaterialFiles{}, err
	}
	return FunctionMaterialFiles{Files: files, ExpiresAt: expires, CredentialExpiresAt: credentialExpires}, nil
}

func (a *Agent) downloadFunctionFile(ctx context.Context, binding FunctionMaterialBinding, generation uint64,
	name, manifest string, expires, credentialExpires time.Time,
) (contents []byte, currentManifest string, currentExpiry, currentCredentialExpiry time.Time, resultErr error) {
	defer func() {
		if resultErr != nil {
			clear(contents)
		}
	}()
	var digest string
	total := 0
	for total == 0 || len(contents) < total {
		if _, _, err := a.executionLease(); err != nil {
			return contents, "", time.Time{}, time.Time{}, err
		}
		private, err := ecdh.X25519().GenerateKey(rand.Reader)
		if err != nil {
			return contents, "", time.Time{}, time.Time{}, err
		}
		query := functionMaterialQuery{Binding: binding, RegistrationGeneration: generation,
			File: name, Offset: len(contents), Length: functionMaterialChunkSize(name), EphemeralPublicKey: private.PublicKey().Bytes()}
		var reply functionMaterialReply
		req, err := a.sendToLeader(ctx, "function-material", query, &reply, nil, nil)
		if err != nil {
			return contents, "", time.Time{}, time.Time{}, err
		}
		if reply.File != name || reply.Offset != query.Offset || reply.Total < 1 || reply.Total > functionMaterialLimit(name) ||
			!lowerHex(reply.SHA256, 64) || !lowerHex(reply.ManifestSHA256, 64) || !time.Now().Before(reply.ExpiresAt) || !time.Now().Before(reply.CredentialExpiresAt) || reply.ExpiresAt.After(reply.CredentialExpiresAt) ||
			len(reply.EphemeralPublicKey) != 32 || len(reply.Nonce) != 12 ||
			total != 0 && (reply.Total != total || reply.SHA256 != digest) ||
			manifest != "" && (reply.ManifestSHA256 != manifest || !reply.ExpiresAt.Equal(expires) || !reply.CredentialExpiresAt.Equal(credentialExpires)) {
			return contents, "", time.Time{}, time.Time{}, errors.New("function material chunk identity changed")
		}
		public, err := ecdh.X25519().NewPublicKey(reply.EphemeralPublicKey)
		if err != nil {
			return contents, "", time.Time{}, time.Time{}, err
		}
		shared, err := private.ECDH(public)
		if err != nil {
			return contents, "", time.Time{}, time.Time{}, err
		}
		aad, err := materialAAD(req, query)
		if err != nil {
			clear(shared)
			return contents, "", time.Time{}, time.Time{}, err
		}
		aead, err := materialAEAD(shared, aad)
		clear(shared)
		if err != nil {
			return contents, "", time.Time{}, time.Time{}, err
		}
		chunk, err := aead.Open(nil, reply.Nonce, reply.Ciphertext, aad)
		if err != nil || len(chunk) == 0 || len(chunk) > query.Length || len(contents)+len(chunk) > reply.Total {
			clear(chunk)
			return contents, "", time.Time{}, time.Time{}, errors.New("function material chunk cannot be authenticated")
		}
		contents = append(contents, chunk...)
		clear(chunk)
		total, digest = reply.Total, reply.SHA256
		manifest, expires, credentialExpires = reply.ManifestSHA256, reply.ExpiresAt, reply.CredentialExpiresAt
	}
	sum := sha256.Sum256(contents)
	if hex.EncodeToString(sum[:]) != digest {
		return contents, "", time.Time{}, time.Time{}, errors.New("function material file digest changed")
	}
	return contents, manifest, expires, credentialExpires, nil
}

wire.text:
func signRequest(r *request, key ed25519.PrivateKey, cell string) error {
	if len(key) != ed25519.PrivateKeySize {
		return errors.New("invalid host identity key")
	}
	payload, err := json.Marshal(r)
	if err != nil {
		return err
	}
	r.Envelope, err = protocol.SignEnvelope(payload, protocol.EnvelopeScope{Region: cell, Kind: "host." + r.Operation, Actor: r.Node, OperationID: entityid.Derive("host-request", r.Nonce), Epoch: r.Epoch}, r.IssuedAt, r.IssuedAt.Add(requestTTL), key)
	return err
}

func verifyRequest(r request, key ed25519.PublicKey, cell string, now time.Time) error {
	if r.Version != 1 || !lowerHex(r.Nonce, 32) || !entityid.Valid(r.SessionID) || r.IssuedAt.IsZero() || r.IssuedAt.After(now.Add(maxClockSkew)) || now.Sub(r.IssuedAt) >= requestTTL {
		return errors.New("invalid or expired host request")
	}
	if !r.Envelope.IssuedAt.Equal(r.IssuedAt) || r.Envelope.Epoch != r.Epoch {
		return errors.New("host request envelope binding mismatch")
	}
	return protocol.VerifyEnvelope(r.Envelope, protocol.EnvelopeScope{Region: cell, Kind: "host." + r.Operation, Actor: r.Node, OperationID: entityid.Derive("host-request", r.Nonce), Epoch: r.Epoch}, key, now, protocol.VerifyPolicy{MaxLifetime: requestTTL, ClockSkew: maxClockSkew})
}

func decodeStrict(data []byte, destination any) error {
	return protocol.DecodeStrict(data, destination, 512<<10)
}

func exchange(ctx context.Context, conn *nats.Conn, cell string, controllerKey ed25519.PublicKey, r request, out any) error {
	return exchangeWithEnvelope(ctx, conn, cell, controllerKey, r, out, nil)
}

func exchangeWithEnvelope(ctx context.Context, conn *nats.Conn, cell string, controllerKey ed25519.PublicKey,
	r request, out any, signedOut *protocol.Envelope,
) error {
	if conn == nil {
		return errors.New("NATS connection is required")
	}
	data, err := protocol.EncodeJSON(r.Envelope)
	if err != nil {
		return err
	}
	if len(data) > 64<<10 {
		return errors.New("host request is too large")
	}
	subject, err := protocol.AgentObservationSubject(cell, r.NATSUserPublicKey, r.Operation)
	if err != nil {
		return err
	}
	timeout := 5 * time.Second
	if r.Operation == "material" || r.Operation == "function-material" || r.Operation == "volume-init" || r.Operation == "runtime-effect" || r.Operation == "container-material" || r.Operation == "registry-admission" {
		timeout = 30 * time.Second
	}
	deadline, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	msg, err := conn.RequestMsgWithContext(deadline, &nats.Msg{Subject: subject, Data: data, Header: observability.TraceHeader(ctx, nil)})
	if err != nil {
		return err
	}
	if len(msg.Data) > 512<<10 {
		return errors.New("host response is too large")
	}
	var signed protocol.Envelope
	if err := protocol.DecodeStrict(msg.Data, &signed, 512<<10); err != nil {
		return err
	}
	if err := protocol.VerifyEnvelope(signed, protocol.EnvelopeScope{Region: cell, Kind: "host.response." + r.Operation, Actor: "controller", OperationID: entityid.Derive("host-request", r.Nonce), Epoch: r.Epoch}, controllerKey, time.Now().UTC(), protocol.VerifyPolicy{MaxLifetime: requestTTL, ClockSkew: maxClockSkew}); err != nil {
		return err
	}
	var result response
	if err := decodeStrict([]byte(signed.Payload), &result); err != nil {
		return err
	}
	if result.Nonce != r.Nonce || result.Node != r.Node || result.SessionID != r.SessionID || result.Epoch != r.Epoch || result.Operation != r.Operation {
		return errors.New("host response binding mismatch")
	}
	if result.Error != "" {
		if strings.HasPrefix(result.Error, authority.ErrNotLeader.Error()) {
			return fmt.Errorf("%w: %s", errControllerNotLeader, result.Error)
		}
		if result.Retryable {
			if result.Error == errSessionContention.Error() {
				return errSessionContention
			}
			if r.Operation == "session" {
				return fmt.Errorf("%w: %s", errSessionBackendUnavailable, result.Error)
			}
			return errArtifactPreparing
		}
		if r.Operation == "session" {
			if result.Error == errSessionOwned.Error() {
				return errSessionOwned
			}
			return fmt.Errorf("%w: %s", errSessionRequestDenied, result.Error)
		}
		return fmt.Errorf("host request denied: %s", result.Error)
	}
	if out != nil {
		if err := decodeStrict(result.Payload, out); err != nil {
			return err
		}
	}
	if signedOut != nil {
		*signedOut = signed
	}
	return nil
}

agent_new.text:
func NewAgent(cfg AgentConfig) (*Agent, error) {
	for name, value := range map[string]string{"cell": cfg.Cell, "node": cfg.Node, "environment": cfg.Environment} {
		if err := validateToken(value, name); err != nil {
			return nil, err
		}
	}
	if cfg.TSAuthPort != 0 && (cfg.TSAuthPort < 1 || cfg.TSAuthPort > 65535) {
		return nil, errors.New("ts-auth port must be between 1 and 65535")
	}
	if cfg.Conn == nil || len(cfg.Identity) != ed25519.PrivateKeySize || len(cfg.ControllerPublicKey) != ed25519.PublicKeySize {
		return nil, errors.New("agent requires NATS connection, Ed25519 identity and pinned controller public key")
	}
	if !nkeys.IsValidPublicUserKey(cfg.NATSUserPublicKey) {
		return nil, errors.New("agent requires its authenticated NATS user public key")
	}
	if cfg.ClockCheck == nil {
		return nil, errors.New("agent requires a fresh host clock health check")
	}
	if len(cfg.Roles) == 0 || len(cfg.Roles) > 32 {
		return nil, errors.New("agent requires roles")
	}
	for i, role := range cfg.Roles {
		if err := validateToken(role, "role"); err != nil {
			return nil, err
		}
		if slices.Contains(cfg.Roles[:i], role) {
			return nil, errors.New("duplicate agent role")
		}
	}
	if err := ValidateWorkloadPaths(cfg.InstallRoot, cfg.StateRoot, cfg.WorkloadIdentity); err != nil {
		return nil, err
	}
	if err := ValidatePrivateHostState(cfg.StateRoot, cfg.Cell, cfg.Node); err != nil {
		return nil, err
	}
	if cfg.ManagedRuntimeRoot != "" {
		if !filepath.IsAbs(cfg.ManagedRuntimeRoot) || filepath.Clean(cfg.ManagedRuntimeRoot) != cfg.ManagedRuntimeRoot ||
			cfg.ManagedRuntimeRoot == cfg.InstallRoot || cfg.ManagedRuntimeRoot == cfg.StateRoot ||
			strings.HasPrefix(cfg.ManagedRuntimeRoot, cfg.InstallRoot+string(filepath.Separator)) ||
			strings.HasPrefix(cfg.ManagedRuntimeRoot, cfg.StateRoot+string(filepath.Separator)) ||
			strings.HasPrefix(cfg.InstallRoot, cfg.ManagedRuntimeRoot+string(filepath.Separator)) ||
			strings.HasPrefix(cfg.StateRoot, cfg.ManagedRuntimeRoot+string(filepath.Separator)) {
			return nil, errors.New("managed runtime root must be clean, absolute and separate from host roots")
		}
	}
	if cfg.TerraBaseRoot != "" {
		if err := validateTerraBaseRoot(cfg.TerraBaseRoot, cfg.InstallRoot, cfg.StateRoot, cfg.WorkloadIdentity); err != nil {
			return nil, err
		}
	}
	if cfg.TSAuthRoot != "" {
		if err := validateWorkloadRoot("ts-auth", cfg.TSAuthRoot, cfg.WorkloadIdentity, cfg.InstallRoot, cfg.StateRoot,
			cfg.TerraBaseRoot); err != nil {
			return nil, err
		}
	}
	for role, limit := range cfg.RoleMemoryMaxBytes {
		if !slices.Contains(cfg.Roles, role) || limit == 0 || validateCgroupMemoryMax(limit) != nil {
			return nil, fmt.Errorf("role %q memory cap must name a host role and be a nonzero page-aligned byte count", role)
		}
	}
	if cfg.TerraBaseDataVolume && cfg.TerraBaseRoot == "" {
		return nil, errors.New("a terrabase data volume needs a terrabase root")
	}
	if cfg.TerraBaseDataVolume && !strings.HasPrefix(cfg.TerraBaseDataVolumeID, "ocid1.volume.") {
		return nil, errors.New("a terrabase data volume needs its recorded volume OCID")
	}
	if cfg.PollInterval == 0 {
		cfg.PollInterval = 5 * time.Second
	}
	if cfg.PollInterval < 100*time.Millisecond {
		return nil, errors.New("agent poll interval is too short")
	}
	runner := cfg.Runner
	if runner == nil {
		runner = NewProcessRunner(filepath.Join(cfg.StateRoot, cfg.Cell, cfg.Node), cfg.WorkloadIdentity, cfg.Cell, cfg.Node)
	}
	id, err := randomID()
	if err != nil {
		return nil, err
	}
	return &Agent{cfg: cfg, runner: runner, processID: id, pending: make(map[string]pendingCycle),
		terraBase: make(map[string]terraBaseMember), nativeRoots: make(map[string]*managedNativeRoot)}, nil
}

agent_run.text:
func (a *Agent) Run(ctx context.Context) error {
	if err := a.runner.Recover(ctx); err != nil {
		return fmt.Errorf("recover native workloads: %w", err)
	}
	work, cancel := context.WithCancel(ctx)
	defer cancel()
	defer func() {
		stopCtx, stopCancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer stopCancel()
		_ = a.runner.Close(stopCtx)
	}()
	defer a.stopAllManagedNativeRoots()
	if err := a.checkClock(); err != nil {
		return err
	}
	if a.cfg.Initialized != nil {
		a.cfg.Initialized()
	}
	if err := a.waitForSession(work); err != nil {
		return err
	}
	lost := make(chan error, 1)
	go a.maintainSession(work, cancel, lost)
	if a.cfg.ManagedRuntimeRoot != "" {
		go a.refreshNativeRootPins(work)
	}
	go a.publishLoad(work)
	go a.publishLogs(work)
	if a.cfg.FollowRollouts != nil {
		go a.cfg.FollowRollouts(work, a)
	}
	if a.cfg.FollowNetBird != nil {
		go a.cfg.FollowNetBird(work, a)
	}
	ticker := time.NewTicker(a.cfg.PollInterval)
	defer ticker.Stop()
	type roleFailure struct {
		class string
		at    time.Time
	}
	failures := make(map[string]roleFailure)
	for {
		ctx := observability.StartTrace(ctx)
		for _, role := range a.cfg.Roles {
			if err := work.Err(); err != nil {
				break
			}
			if a.sessionLost.Load() {
				break
			}
			err := a.reconcile(work, role)
			if a.cfg.ManagedRuntimeRoot == "" || work.Err() != nil || a.sessionLost.Load() {
				continue
			}
			if err == nil {
				if _, failed := failures[role]; failed {
					slog.InfoContext(ctx, "managed host reconciliation recovered", "role", role)
					delete(failures, role)
				}
				continue
			}
			class := managedReconcileErrorClass(err)
			previous := failures[role]
			if class != previous.class || time.Since(previous.at) >= 10*time.Second {
				// A repeated cause is still logged, but only at DEBUG.
				level := slog.LevelDebug
				if class != previous.class {
					level = slog.LevelWarn
				}
				slog.Log(ctx, level, "managed host reconciliation deferred", "role", role, "cause_class", class)
				failures[role] = roleFailure{class: class, at: time.Now()}
			}
		}
		select {
		case err := <-lost:
			return err
		case <-ctx.Done():
			return ctx.Err()
		case <-work.Done():
			if a.sessionLost.Load() {
				// Session loss cancels work before workload shutdown finishes.
				// Wait for its reason so a supervisor sees a failed host.
				return <-lost
			}
			return work.Err()
		case <-ticker.C:
		}
	}
}

agent_request_lease.text:
func (a *Agent) makeRequest(operation string, payload any) (request, error) {
	data, err := json.Marshal(payload)
	if err != nil {
		return request{}, err
	}
	nonce, err := randomNonce()
	if err != nil {
		return request{}, err
	}
	a.mu.RLock()
	s := a.session
	a.mu.RUnlock()
	r := request{Version: 1, CredentialProtocol: 1, Node: a.cfg.Node, NATSUserPublicKey: a.cfg.NATSUserPublicKey, Operation: operation, SessionID: a.processID, Epoch: s.Epoch, Nonce: nonce, IssuedAt: time.Now().UTC(), Payload: data}
	if err := signRequest(&r, a.cfg.Identity, a.cfg.Cell); err != nil {
		return request{}, err
	}
	return r, nil
}

// sendToLeader builds, signs and sends a fresh request, and sends a new one
// when a follower controller denies it: every controller of the cell serves
// the host subjects, but only the authority leader answers effectful requests.
// It returns the request whose reply was accepted.
func (a *Agent) sendToLeader(ctx context.Context, operation string, payload, out any,
	signedOut *protocol.Envelope, prepare func(*request) error,
) (request, error) {
	for attempt := 1; ; attempt++ {
		r, err := a.makeRequest(operation, payload)
		if err != nil {
			return request{}, err
		}
		if prepare != nil {
			if err := prepare(&r); err != nil {
				return request{}, err
			}
		}
		err = exchangeWithEnvelope(ctx, a.cfg.Conn, a.cfg.Cell, a.cfg.ControllerPublicKey, r, out, signedOut)
		if !errors.Is(err, errControllerNotLeader) || attempt == leaderRequestAttempts {
			return r, err
		}
		select {
		case <-ctx.Done():
			return request{}, ctx.Err()
		case <-time.After(time.Duration(attempt) * leaderRetryBackoff):
		}
	}
}

func (a *Agent) acquire(ctx context.Context) error {
	if err := a.checkClock(); err != nil {
		return err
	}
	var s session
	if _, err := a.sendToLeader(ctx, "session", struct {
		Kind string `json:"kind"`
	}{"acquire"}, &s, nil, func(r *request) error {
		r.Epoch = 0
		return signRequest(r, a.cfg.Identity, a.cfg.Cell)
	}); err != nil {
		return fmt.Errorf("acquire host session: %w", err)
	}
	if s.SessionID != a.processID || s.Epoch == 0 {
		return errors.New("invalid acquired host session")
	}
	if err := a.acceptSession(s); err != nil {
		return err
	}
	a.logSessionAccepted("acquire", s)
	return nil
}

func (a *Agent) waitForSession(ctx context.Context) error {
	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()
	for {
		ctx := observability.StartTrace(ctx)
		if err := a.acquire(ctx); err == nil {
			a.sessionRecovered()
			return nil
		} else if !retrySessionExchange(err) && !errors.Is(err, errSessionOwned) {
			a.logSessionFailure("acquire", err, 0)
			return err
		} else {
			a.logSessionFailure("acquire", err, 0)
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
		}
	}
}

func retrySessionExchange(err error) bool {
	return errors.Is(err, errSessionBackendUnavailable) || errors.Is(err, errSessionContention) || transientSessionTransport(err)
}

func sessionUsableUntil(s session, now time.Time) bool {
	return now.Before(s.ExpiresAt.Add(-sessionExecutionReserve))
}

func (a *Agent) checkClock() error {
	if a.cfg.ClockCheck == nil {
		return errors.New("host clock health check is absent")
	}
	if err := a.cfg.ClockCheck(); err != nil {
		return fmt.Errorf("host clock is unhealthy: %w", err)
	}
	return nil
}

func (a *Agent) wallTime() time.Time {
	if a.wallNow != nil {
		return a.wallNow()
	}
	return time.Now()
}

func (a *Agent) acceptSession(s session) error {
	if err := a.checkClock(); err != nil {
		return err
	}
	receivedAt := time.Now()
	remaining := s.ExpiresAt.Sub(a.wallTime()) - sessionExecutionReserve
	if remaining <= 0 || remaining > sessionTTL-sessionExecutionReserve+maxClockSkew {
		return errors.New("signed host session has no execution reserve")
	}
	// receivedAt carries Go's monotonic reading. A later wall-clock step cannot
	// extend this locally bounded execution lease.
	deadline := receivedAt.Add(min(remaining, sessionTTL-sessionExecutionReserve))
	a.mu.Lock()
	a.session = s
	a.sessionSafeUntil = deadline
	a.mu.Unlock()
	return nil
}

func (a *Agent) executionLease() (session, time.Time, error) {
	if err := a.checkClock(); err != nil {
		return session{}, time.Time{}, err
	}
	a.mu.RLock()
	s, deadline := a.session, a.sessionSafeUntil
	a.mu.RUnlock()
	if deadline.IsZero() || !time.Now().Before(deadline) || !sessionUsableUntil(s, a.wallTime()) {
		return session{}, time.Time{}, errSessionExecutionReserve
	}
	return s, deadline, nil
}

agent_withdrawal.text:
func (a *Agent) reconcile(ctx context.Context, role string) (resultErr error) {
	if a.sessionLost.Load() {
		return errors.New("host session was lost")
	}
	if _, _, err := a.executionLease(); err != nil {
		return err
	}
	if _, err := a.fenceTerraBaseMember(ctx, role); err != nil {
		return err
	}
	pending, hasPending := a.pending[role]
	if hasPending && pending.outcomeReady {
		if err := a.flushCycle(ctx, role); err != nil {
			return err
		}
		hasPending = false
	}
	var target desiredReply
	if err := a.request(ctx, "desired", struct {
		Role string `json:"role"`
	}{role}, &target); err != nil {
		return errors.Join(err, a.revokeManagedNativeRoot(role))
	}
	if err := a.validateDesiredReply(target); err != nil {
		return errors.Join(err, a.revokeManagedNativeRoot(role))
	}
	if target.Desired == nil {
		if err := a.revokeManagedNativeRoot(role); err != nil {
			return err
		}
		if hasPending {
			if err := a.failPendingCycle(ctx, role); err != nil {
				return err
			}
		}
		return nil
	}
	d := *target.Desired
	if d.Cell != a.cfg.Cell || d.Node != a.cfg.Node || d.Environment != a.cfg.Environment || d.Role != role || d.Generation == 0 {
		return errors.Join(errors.New("desired identity mismatch"), a.revokeManagedNativeRoot(role))
	}
	if err := validateDesired(d, a.cfg.Cell, *target.Registration); err != nil {
		return errors.Join(err, a.revokeManagedNativeRoot(role))
	}
	if !d.Withdrawn && d.ManagedMember != nil {
		fingerprint, err := desiredFingerprint(d)
		if err != nil {
			return errors.Join(err, a.revokeManagedNativeRoot(role))
		}
		if err := a.pinManagedNativeRootDesired(role, fingerprint); err != nil {
			return errors.Join(err, a.revokeManagedNativeRoot(role))
		}
		if err := a.stopManagedNativeRootIfChanged(role, fingerprint); err != nil {
			return err
		}
	}
	if hasPending && (d.Withdrawn || d.Generation != pending.query.Generation || d.Digest != pending.query.Digest || d.AuthorityEpoch != pending.query.AuthorityEpoch) {
		if err := a.failPendingCycle(ctx, role); err != nil {
			return err
		}
		hasPending = false
	}
	backupObserved := false
	defer func() {
		if resultErr != nil && !backupObserved && !errors.Is(resultErr, errSessionContention) {
			_ = a.publishReport(ctx, a.reportFor(d, "failed", resultErr))
		}
	}()
	if d.Withdrawn {
		if err := a.revokeManagedNativeRoot(role); err != nil {
			return err
		}
		if err := a.runner.Stop(ctx, role); err != nil {
			return err
		}
		return a.publishReport(ctx, a.reportFor(d, "stopped", nil))
	}

agent_cycle_report.text:
func (a *Agent) flushCycle(ctx context.Context, role string) error {
	pending, ok := a.pending[role]
	if !ok || !pending.outcomeReady {
		return nil
	}
	query := pending.query
	var result cycleReply
	if err := a.request(ctx, "cycle", query, &result); err != nil {
		return err
	}
	expected := "failed"
	if query.Succeeded {
		expected = "succeeded"
	}
	if result.CycleID != query.CycleID || result.Fence != query.Fence || result.State != expected {
		return errors.New("cycle outcome receipt mismatch")
	}
	delete(a.pending, role)
	return nil
}

func (a *Agent) failPendingCycle(ctx context.Context, role string) error {
	pending := a.pending[role]
	pending.query.Succeeded = false
	pending.outcomeReady = true
	a.pending[role] = pending
	return a.flushCycle(ctx, role)
}

func (a *Agent) reportFor(d Desired, state string, failure error) Report {
	a.mu.RLock()
	s := a.session
	a.mu.RUnlock()
	r := Report{Cell: a.cfg.Cell, Node: a.cfg.Node, Environment: a.cfg.Environment, Role: d.Role, Digest: d.Digest, Generation: d.Generation, SessionID: s.SessionID, Epoch: s.Epoch, State: state, ObservedAt: time.Now().UTC()}
	if failure != nil {
		r.Error = failure.Error()
	}
	return r
}

func (a *Agent) publishReport(ctx context.Context, r Report) error {
	a.mu.RLock()
	s := a.session
	a.mu.RUnlock()
	r.SessionID = s.SessionID
	r.Epoch = s.Epoch
	if r.Error != "" && len(r.Error) > 1024 {
		r.Error = r.Error[:1024]
	}
	var ack struct {
		Accepted bool `json:"accepted"`
	}
	if err := a.request(ctx, "report", r, &ack); err != nil {
		return err
	}
	if !ack.Accepted {
		return errors.New("report was not accepted")
	}
	return nil
}

cycle_report_store.text:
func (c *Controller) serveCycle(ctx context.Context, req request, r Registration, s session) (any, error) {
	var query cycleQuery
	if err := decodeStrict(req.Payload, &query); err != nil {
		return nil, err
	}
	if !slices.Contains(r.Roles, query.Role) || validateDigest(query.Digest) != nil || query.Generation == 0 || query.AuthorityEpoch == 0 || !entityid.Valid(query.Attempt) {
		return nil, errors.New("invalid cycle query")
	}
	var desired Desired
	if query.CycleID == "" {
		var exists bool
		var err error
		desired, _, exists, err = c.readDesired(ctx, req.Node, query.Role)
		if err != nil {
			return nil, err
		}
		if !exists || desired.Withdrawn || desired.Generation != query.Generation || desired.AuthorityEpoch != query.AuthorityEpoch || desired.Digest != query.Digest {
			return nil, errors.New("cycle target is no longer desired")
		}
	}
	key := cycleKey(c.cell, req.Node, query.Role)
	// granted remembers the restart gate's grant across CAS retries, so one
	// request asks the gate at most once.
	granted := false
	for range 8 {
		var old cycleRecord
		revision, exists, err := c.get(ctx, key, &old)
		if err != nil {
			return nil, err
		}
		if req.Operation != "cycle" {
			return nil, errors.New("invalid cycle operation")
		}
		if query.CycleID == "" {
			if exists && old.Generation > query.Generation {
				return nil, errors.New("cycle generation moved backward")
			}
			if exists && old.Attempt == query.Attempt && old.Digest == query.Digest && old.Generation == query.Generation && old.AuthorityEpoch == query.AuthorityEpoch && old.SessionID == s.SessionID && old.Epoch == s.Epoch {
				if _, err := c.cas(ctx, key, old, revision); err == nil {
					return cycleReply{CycleID: old.CycleID, Fence: old.Fence, State: old.State, NotBefore: old.NotBefore}, nil
				} else if casConflict(err) {
					continue
				} else {
					return nil, err
				}
			}
			if exists && old.State == "active" && old.Generation == query.Generation && old.AuthorityEpoch == query.AuthorityEpoch && old.SessionID == s.SessionID && old.Epoch == s.Epoch {
				return cycleReply{CycleID: old.CycleID, Fence: old.Fence, State: "busy"}, nil
			}
			if exists && old.State == "active" && old.Digest == query.Digest && old.Generation == query.Generation && old.AuthorityEpoch == query.AuthorityEpoch {
				abandoned := old
				abandoned.State = "failed"
				abandoned.Failures = min(old.Failures+1, 6)
				abandoned.NotBefore = time.Now().Add(backoffDuration(abandoned.Failures))
				if _, err := c.cas(ctx, key, abandoned, revision); err == nil {
					return cycleReply{CycleID: old.CycleID, Fence: old.Fence, State: "backoff", NotBefore: abandoned.NotBefore}, nil
				} else if casConflict(err) {
					continue
				} else {
					return nil, err
				}
			}
			if exists && old.Digest == query.Digest && old.Generation == query.Generation && old.AuthorityEpoch == query.AuthorityEpoch && time.Now().Before(old.NotBefore) {
				return cycleReply{CycleID: old.CycleID, Fence: old.Fence, State: "backoff", NotBefore: old.NotBefore}, nil
			}
			// Only opening a new cycle is gated: the agent's revalidation
			// resolves the cycle it already holds above. Managed members stop
			// their workload before they ask, so they are never held; their
			// drain receipts order their restarts.
			if c.restartGate != nil && desired.ManagedMember == nil && !granted {
				ok, err := c.restartGate(ctx, req.Node, desired)
				if err != nil {
					return nil, err
				}
				if !ok {
					return cycleReply{State: "held"}, nil
				}
				granted = true
			}
			id, err := randomID()
			if err != nil {
				return nil, err
			}
			next := cycleRecord{CycleID: id, Fence: 1, Attempt: query.Attempt, Digest: query.Digest, Generation: query.Generation, AuthorityEpoch: query.AuthorityEpoch, SessionID: s.SessionID, Epoch: s.Epoch, State: "active"}
			if exists {
				if old.Fence == ^uint64(0) {
					return nil, errors.New("cycle fence exhausted")
				}
				next.Fence = old.Fence + 1
				if old.Digest == query.Digest && old.Generation == query.Generation && old.AuthorityEpoch == query.AuthorityEpoch {
					next.Failures = old.Failures
				}
			}
			if _, err := c.cas(ctx, key, next, revision); err == nil {
				return cycleReply{CycleID: id, Fence: next.Fence, State: "active"}, nil
			} else if casConflict(err) {
				continue
			} else {
				return nil, err
			}
		}
		if !exists || old.CycleID != query.CycleID || old.Fence != query.Fence || old.Attempt != query.Attempt || old.SessionID != s.SessionID || old.Epoch != s.Epoch || old.Digest != query.Digest || old.Generation != query.Generation || old.AuthorityEpoch != query.AuthorityEpoch {
			return nil, errors.New("cycle outcome fence mismatch")
		}
		if old.State != "active" {
			return cycleReply{CycleID: old.CycleID, Fence: old.Fence, State: old.State, NotBefore: old.NotBefore}, nil
		}
		next := old
		if query.Succeeded {
			next.State = "succeeded"
			next.Failures = 0
		} else {
			next.State = "failed"
			next.Failures = min(old.Failures+1, 6)
			next.NotBefore = time.Now().Add(backoffDuration(next.Failures))
		}
		if _, err := c.cas(ctx, key, next, revision); err == nil {
			return cycleReply{CycleID: old.CycleID, Fence: old.Fence, State: next.State, NotBefore: next.NotBefore}, nil
		} else if casConflict(err) {
			continue
		} else {
			return nil, err
		}
	}
	return nil, errors.New("cycle contention")
}

func backoffDuration(failures int) time.Duration {
	return min(30*time.Second*time.Duration(1<<(max(1, failures)-1)), 15*time.Minute)
}

func (c *Controller) storeReport(ctx context.Context, req request, r Registration, s session) (any, error) {
	var report Report
	if err := decodeStrict(req.Payload, &report); err != nil {
		return nil, err
	}
	if report.Cell != c.cell || report.Node != req.Node || report.Environment != r.Environment || !slices.Contains(r.Roles, report.Role) || report.SessionID != s.SessionID || report.Epoch != s.Epoch ||
		report.ObservedAt.Before(req.IssuedAt.Add(-30*time.Second)) || report.ObservedAt.After(time.Now().Add(maxClockSkew)) || report.ObservedAt.IsZero() || len(report.Error) > 1024 || len(report.State) > 64 {
		return nil, errors.New("report identity or timestamp mismatch")
	}
	desired, _, exists, err := c.readDesired(ctx, req.Node, report.Role)
	if err != nil {
		return nil, err
	}
	if !exists || report.Generation != desired.Generation || report.Digest != desired.Digest {
		return nil, errors.New("report target is not current")
	}
	if err := validateManagedReportForDesired(report, desired); err != nil {
		return nil, err
	}
	key := reportKey(c.cell, req.Node, report.Role)
	for range 8 {
		current, _, exists, err := c.readDesired(ctx, req.Node, report.Role)
		if err != nil || !exists || !sameJSON(current, desired) {
			return nil, errors.New("desired changed before report commit")
		}
		if _, _, err := c.authorize(ctx, req); err != nil {
			return nil, err
		}
		var old Report
		revision, exists, err := c.get(ctx, key, &old)
		if err != nil {
			return nil, err
		}
		if exists {
			if report.Generation < old.Generation || report.Generation == old.Generation && report.ObservedAt.Before(old.ObservedAt) {
				return nil, errors.New("report ordering moved backward")
			}
			if report.Generation == old.Generation && report.ObservedAt.Equal(old.ObservedAt) && !sameJSON(report, old) {
				return nil, errors.New("report timestamp collision")
			}
		}
		_, err = c.cas(ctx, key, report, revision)
		if err == nil {
			current, _, exists, checkErr := c.readDesired(ctx, req.Node, report.Role)
			if checkErr != nil || !exists || !sameJSON(current, desired) {
				return nil, errors.New("desired changed during report commit")
			}
			return struct {
				Accepted bool `json:"accepted"`
			}{true}, nil
		}
		if !casConflict(err) {
			return nil, fmt.Errorf("store report: %w", err)
		}
	}
	return nil, errors.New("report contention")
}

load_store.text:
func (c *Controller) SetLoadObservationSink(sink LoadObservationSink) {
	c.loadObservationSink.Store(&sink)
}

type loadAck struct {
	Accepted bool `json:"accepted"`
}

// SetLoadSink enables the "load" host operation; nil disables it again.
func (c *Controller) SetLoadSink(sink LoadSink) {
	if sink == nil {
		c.loadSink.Store(nil)
		return
	}
	c.loadSink.Store(&sink)
}

func (c *Controller) storeLoad(ctx context.Context, req request, r Registration) (any, error) {
	sink := c.loadSink.Load()
	observationSink := c.loadObservationSink.Load()
	if sink == nil && observationSink == nil {
		return nil, errLoadDisabled
	}
	epoch := c.authorityEpoch()
	var report hostload.Report
	if err := decodeStrict(req.Payload, &report); err != nil {
		return nil, err
	}
	if err := report.Validate(); err != nil {
		return nil, err
	}
	var taskRoles []string
	if c.taskLoadRoles != nil {
		var err error
		taskRoles, err = c.taskLoadRoles(ctx, r)
		if err != nil {
			return nil, err
		}
	}
	// Only roles registered for this host with a current, non-withdrawn
	// allocation count: a host cannot report load for a service it does
	// not run.
	roles := make([]hostload.RoleUsage, 0, len(r.Roles))
	for _, name := range r.Roles {
		taskRole := c.taskLoadRoles != nil && name != terrabase.Role
		if taskRole && !slices.Contains(taskRoles, name) {
			continue
		}
		var desired Desired
		if !taskRole {
			var exists bool
			var err error
			desired, _, exists, err = c.readDesired(ctx, req.Node, name)
			if err != nil {
				return nil, err
			}
			if !exists || desired.Withdrawn || validateDesired(desired, c.cell, r) != nil {
				continue
			}
		}
		// Reservations survive missing cgroup measurements or a stopped process.
		role := hostload.RoleUsage{Role: name}
		for _, measured := range report.Roles {
			if measured.Role == name {
				role = measured
				break
			}
		}
		if taskRole {
			role.TerraBase, role.WAN = nil, nil
		}
		if role.WAN != nil {
			if name != terrabase.Role || desired.ManagedMember != nil || !role.WAN.Fresh(time.Now()) ||
				role.WAN.ReceiverRegion != desired.Env[terrabase.EnvRegion] {
				role.WAN = nil
			}
		}
		roles = append(roles, role)
	}
	report.Roles = roles
	if err := c.recheckReplyAuthority(ctx, epoch, req, r, false); err != nil {
		return nil, err
	}
	origin := hostload.Origin{Cell: c.cell, Environment: r.Environment, Node: req.Node}
	var err error
	if observationSink != nil {
		caller := &loadObservationCaller{controller: c, request: req, registration: r}
		caller.active.Store(true)
		err = func() error {
			defer caller.active.Store(false)
			return (*observationSink)(context.WithValue(ctx, loadObservationContextKey{}, caller), origin, report)
		}()
	} else {
		err = (*sink)(origin, report)
	}
	if errors.Is(err, hostload.ErrTooFrequent) {
		return loadAck{Accepted: false}, nil
	}
	if err != nil {
		return nil, err
	}
	return loadAck{Accepted: true}, nil
}

load_expiry.text:
func (a *Agent) noteTerraBaseLoad(role string, load *memberstatus.Load) {
	a.loadMu.Lock()
	defer a.loadMu.Unlock()
	if load == nil {
		delete(a.terraBaseLoads, role)
		return
	}
	if a.terraBaseLoads == nil {
		a.terraBaseLoads = make(map[string]terraBaseLoad)
	}
	a.terraBaseLoads[role] = terraBaseLoad{load: *load, at: time.Now()}
}

func (a *Agent) currentTerraBaseLoads() map[string]memberstatus.Load {
	a.loadMu.Lock()
	defer a.loadMu.Unlock()
	// A running member's block is refreshed on every poll, so one that
	// missed a few polls (withdrawn, draining, or stuck) is dropped well
	// before the absolute cap.
	ttl := min(max(3*a.cfg.PollInterval, minTerraBaseLoadTTL), terraBaseLoadTTL)
	out := make(map[string]memberstatus.Load, len(a.terraBaseLoads))
	for role, entry := range a.terraBaseLoads {
		if time.Since(entry.at) > ttl {
			delete(a.terraBaseLoads, role)
			continue
		}
		out[role] = entry.load
	}
	return out
}

load_filesystems.text:
func (a *Agent) loadFilesystems() []observability.FilesystemRole {
	filesystems := []observability.FilesystemRole{{Role: "boot", Path: "/"}, {Role: "state", Path: a.cfg.StateRoot},
		{Role: "install", Path: a.cfg.InstallRoot}}
	if a.cfg.ManagedRuntimeRoot != "" {
		filesystems = append(filesystems, observability.FilesystemRole{Role: "managed_runtime", Path: a.cfg.ManagedRuntimeRoot})
	}
	if a.cfg.TerraBaseRoot != "" {
		filesystems = append(filesystems, observability.FilesystemRole{Role: "terrabase_data", Path: terrabase.Layout(a.cfg.TerraBaseRoot).Data()})
	}
	a.nativeRootMu.Lock()
	defer a.nativeRootMu.Unlock()
	// shortcut: generic S3 members have no tracked mount path; add runtime mount tracking when they need filesystem telemetry.
	for _, role := range a.cfg.Roles {
		root := a.nativeRoots[role]
		if root == nil {
			continue
		}
		select {
		case <-root.done:
			continue
		default:
		}
		member := filepath.Dir(root.path)
		filesystems = append(filesystems, observability.FilesystemRole{
			Role: "managed_volume_" + filepath.Base(member), Path: filepath.Join(member, "volume")})
	}
	return filesystems
}

load_publish.text:
func (a *Agent) publishLoad(ctx context.Context) {
	config := hostload.SamplerConfig{Roles: a.cfg.Roles,
		ReadSystem: func([]observability.FilesystemRole) (observability.SystemView, error) {
			return observability.ReadSystem(a.loadFilesystems())
		}}
	if rooted, ok := a.runner.(cgroupRooted); ok {
		config.CgroupRoot = rooted.CgroupRoot()
	}
	sampler := hostload.NewSampler(config)
	// The first sample only sets CPU baselines.
	_, _ = a.sampleLoad(ctx, sampler)
	wait, failing := loadInterval, false
	for {
		select {
		case <-ctx.Done():
			return
		case <-time.After(wait):
		}
		ctx := observability.StartTrace(ctx)
		if a.sessionLost.Load() {
			return
		}
		var ack loadAck
		report, err := a.sampleLoad(ctx, sampler)
		if err == nil {
			err = a.request(ctx, "load", report, &ack)
		}
		if ctx.Err() != nil {
			return
		}
		if err := loadOutcome(err, ack); err != nil {
			if !failing {
				slog.InfoContext(ctx, "host load telemetry not accepted; backing off", "error_class", loadErrorClass(err))
			}
			failing = true
			wait = nextLoadWait(wait)
			continue
		}
		if failing {
			slog.InfoContext(ctx, "host load telemetry accepted")
		}
		failing, wait = false, loadInterval
	}
}

func (a *Agent) sampleLoad(ctx context.Context, sampler *hostload.Sampler) (hostload.Report, error) {
	report := sampler.Sample(a.currentTerraBaseLoads())
	a.addTerraBaseWAN(ctx, &report)
	if a.cfg.TaskLoad == nil {
		return report, nil
	}
	tasks, err := a.cfg.TaskLoad.ReadTaskLoad(ctx)
	if err != nil {
		return hostload.Report{}, err
	}
	if err := (hostload.Report{SchemaVersion: hostload.SchemaVersion, Roles: tasks}).Validate(); err != nil {
		return hostload.Report{}, err
	}
	for _, task := range tasks {
		if task.Role == terrabase.Role || !slices.Contains(a.cfg.Roles, task.Role) {
			continue
		}
		task.TerraBase, task.WAN = nil, nil
		index := slices.IndexFunc(report.Roles, func(role hostload.RoleUsage) bool { return role.Role == task.Role })
		if index < 0 {
			report.Roles = append(report.Roles, task)
		} else {
			report.Roles[index] = task
		}
	}
	return report, report.Validate()
}

load_policy.text:
func nextLoadWait(wait time.Duration) time.Duration {
	return max(min(wait*2, maxLoadBackoff), loadInterval)
}

// loadOutcome treats a reply whose sample the controller discarded (it
// arrived inside the controller's minimum interval) as a rejection that
// backs off, not as a success.
func loadOutcome(err error, ack loadAck) error {
	if err == nil && !ack.Accepted {
		return errLoadThrottled
	}
	return err
}

func loadErrorClass(err error) string {
	switch {
	case errors.Is(err, context.DeadlineExceeded):
		return "timeout"
	case errors.Is(err, errLoadThrottled):
		return "throttled"
	case strings.Contains(err.Error(), errLoadDisabled.Error()):
		return "disabled"
	default:
		return "other"
	}
}

desired_validate.text:
func validateDesired(d Desired, cell string, r Registration) error {
	if d.Cell != cell || d.Node != r.Node || d.Environment != r.Environment {
		return errors.New("desired identity mismatch")
	}
	if err := validateToken(d.Role, "role"); err != nil {
		return err
	}
	if !slices.Contains(r.Roles, d.Role) {
		return errors.New("role is not registered")
	}
	if (r.ManagedOCI == nil) != (d.ManagedMember == nil) {
		return errors.New("managed desired and registration kind differ")
	}
	if d.ManagedMember != nil {
		if r.ManagedMember == nil {
			return errors.New("managed registration lacks member binding")
		}
		if d.Role != "terrabase" || *r.ManagedOCI != d.ManagedMember.OCI ||
			*r.ManagedMember != d.ManagedMember.Member {
			return errors.New("managed desired binding differs from registration")
		}
		if err := validateManagedMemberLaunch(*d.ManagedMember, d, r); err != nil {
			return err
		}
	}
	if d.Generation == 0 {
		return errors.New("desired generation must be positive")
	}
	if d.Withdrawn {
		if d.Digest != "" || len(d.Args) != 0 || len(d.Env) != 0 || len(d.Secrets) != 0 {
			return errors.New("withdrawn desired contains execution data")
		}
	} else if err := validateDigest(d.Digest); err != nil {
		return err
	}
	if len(d.Args) > 64 || len(d.Env) > 64 {
		return errors.New("too many workload arguments or environment variables")
	}
	for _, arg := range d.Args {
		if len(arg) > 4096 {
			return errors.New("argument too long")
		}
	}
	for key, value := range d.Env {
		if !regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`).MatchString(key) || len(value) > 4096 {
			return errors.New("invalid workload environment")
		}
	}
	// A C# TerraBase member's environment is host-owned: it takes only
	// secret files, whose paths the host sets.
	for key := range d.Secrets {
		if d.Role == terrabase.Role && !vaultsecret.FileKey(key) {
			return errors.New("terrabase takes only Vault secret files (keys ending in _FILE)")
		}
		if roleidentity.Reserved(d.Role, key) {
			return fmt.Errorf("the host sets %s for %s's NATS identity", key, d.Role)
		}
	}
	for key := range d.Env {
		if roleidentity.Reserved(d.Role, key) {
			return fmt.Errorf("the host sets %s for %s's NATS identity", key, d.Role)
		}
	}
	return vaultsecret.ValidateRefs(d.Cell, d.Role, d.Secrets, d.Env)
}

func validateManagedMemberLaunch(launch ManagedMemberLaunch, d Desired, r Registration) error {
	if len(d.Args) != 0 || len(d.Env) != 0 || len(d.Secrets) != 0 {
		return errors.New("managed desired cannot carry arbitrary arguments or environment")
	}
	if validateDigest(launch.SourceDigest) != nil ||
		!strings.HasPrefix(launch.VolumeID, "ocid1.volume.") ||
		!strings.HasPrefix(launch.AttachmentID, "ocid1.volumeattachment.") ||
		len(launch.VolumeID) > 255 || len(launch.AttachmentID) > 255 ||
		strings.ContainsFunc(launch.VolumeID, unicode.IsSpace) || strings.ContainsFunc(launch.AttachmentID, unicode.IsSpace) ||
		launch.Authority.Epoch == 0 ||
		!lowerHex(launch.Authority.ConfigurationID, 64) ||
		!lowerHex(launch.Authority.CertificateSHA256, 64) ||
		!lowerHex(launch.Authority.TLSLeafSHA256, 64) {
		return errors.New("managed launch source, volume or authority is invalid")
	}
	if d.Withdrawn {
		if launch.ProcessMemoryBytes != 0 || launch.MemoryHeadroomBytes != 0 || launch.CgroupMemoryMaxBytes != 0 || launch.SystemReserveBytes != 0 || launch.Runtime != nil {
			return errors.New("withdrawn managed desired contains memory execution data")
		}
		return nil
	}
	const gib = uint64(1 << 30)
	p, h, c := launch.ProcessMemoryBytes, launch.MemoryHeadroomBytes, launch.CgroupMemoryMaxBytes
	if p < 4*gib || h < max(gib, p/4) || h >= p || launch.SystemReserveBytes == 0 ||
		launch.SystemReserveBytes > math.MaxInt64 || launch.SystemReserveBytes != uint64(r.SystemReserveBytes) ||
		validateCgroupMemoryMax(c) != nil || c < p || c > uint64(r.Capacity.MemoryBytes) ||
		p > math.MaxInt64 || h > math.MaxInt64 || p%uint64(os.Getpagesize()) != 0 || h%uint64(os.Getpagesize()) != 0 {
		return errors.New("managed process memory, headroom or cgroup cap is invalid")
	}
	if launch.Runtime != nil {
		if launch.AttachmentETag == "" {
			return errors.New("managed runtime requires an exact attachment ETag")
		}
		if err := validateManagedRuntimePins(*launch.Runtime); err != nil {
			return err
		}
	}
	return nil
}

credential_protocol.text:
func (c *Controller) verifyCredentialProtocol(ctx context.Context, request request, registration Registration) error {
	if registration.ManagedPlacement == nil || c.credentialFloor == nil {
		return nil
	}
	generation, err := c.credentialFloor(ctx, registration)
	if err != nil || generation == 0 {
		return errors.New("managed credential floor is unavailable")
	}
	if generation > 1 && request.CredentialProtocol < 1 {
		return errors.New("host credential protocol cannot enforce the committed generation")
	}
	return nil
}

function_binding.text:
func (binding FunctionBinding) Validate() error {
	if !functionSwarmID.MatchString(binding.TaskID) || !functionSwarmID.MatchString(binding.ServiceID) ||
		!functionSwarmID.MatchString(binding.NodeID) || !entityid.Valid(binding.HostID) ||
		!catalog.IsOCIRegion(binding.Region) || !strings.HasPrefix(binding.InstanceID, "ocid1.instance.") ||
		len(binding.InstanceID) <= len("ocid1.instance.") || len(binding.InstanceID) > 255 ||
		strings.ContainsFunc(binding.InstanceID, unicode.IsSpace) ||
		!validTerminalDigest(binding.Fingerprint) || !validTerminalDigest(binding.MaterialManifestSHA256) {
		return errors.New("function grant recipient or material identity is invalid")
	}
	return nil
}

function_intent.text:
func (r *Runtime) CommitFunctionIntent(ctx context.Context, epoch uint64, operationID string,
	expectedSequence uint64, proof release.VerifiedFunction,
) (uint64, error) {
	if !proof.Valid() {
		return 0, trust.ErrExpired
	}
	intent := FunctionIntent{Claim: proof.Claim(), EnvelopeSHA256: proof.EnvelopeSHA256(),
		Envelope: proof.Envelope(), Delegation: proof.Delegation()}
	key, err := functionIntentKey(intent.Claim.TenantID, intent.Claim.FunctionID)
	if err != nil {
		return 0, err
	}
	if r == nil || strings.ToLower(intent.Claim.Cell) != r.config.Scope {
		return 0, release.ErrExpectationMismatch
	}
	payload, err := json.Marshal(intent, json.FormatNilSliceAsNull(true))
	if err != nil {
		return 0, err
	}
	return r.commitMutationVerified(ctx, epoch, MutationFunctionIntent, key, operationID,
		expectedSequence, payload, func(ctx context.Context) error {
			if !proof.Valid() {
				return trust.ErrExpired
			}
			prior, err := r.ReadFunctionIntent(ctx, intent.Claim.TenantID, intent.Claim.FunctionID)
			if !proof.Valid() {
				return trust.ErrExpired
			}
			if errors.Is(err, ErrNotFound) {
				return nil
			}
			if err != nil {
				return err
			}
			current, err := DecodeFunctionIntent(prior)
			if err != nil {
				return err
			}
			if intent.Claim.Sequence < current.Claim.Sequence ||
				intent.Claim.Sequence == current.Claim.Sequence && !bytes.Equal(payload, prior.Payload) {
				return ErrConflict
			}
			return nil
		})
}

function_grant.text:
// VerifyFunctionIntent compares an already verified, still-current signature
// against the durable floor. Readers must separately verify retained wire with
// their trusted roots and module bytes before producing a sealed proof.
func (r *Runtime) VerifyFunctionIntent(ctx context.Context, proof release.VerifiedFunction) error {
	return verifyFunctionIntent(ctx, r, proof)
}

func (r *Reader) VerifyFunctionIntent(ctx context.Context, proof release.VerifiedFunction) error {
	return verifyFunctionIntent(ctx, r, proof)
}

type functionIntentReader interface {
	ReadFunctionIntent(context.Context, string, string) (LogEntry, error)
}

func verifyFunctionIntent(ctx context.Context, reader functionIntentReader, proof release.VerifiedFunction) error {
	if !proof.Valid() {
		return trust.ErrExpired
	}
	claim := proof.Claim()
	entry, err := reader.ReadFunctionIntent(ctx, claim.TenantID, claim.FunctionID)
	if err != nil {
		return err
	}
	current, err := DecodeFunctionIntent(entry)
	if err != nil {
		return err
	}
	if current.Claim.Sequence != claim.Sequence || current.EnvelopeSHA256 != proof.EnvelopeSHA256() ||
		!bytes.Equal(current.Envelope, proof.Envelope()) || !bytes.Equal(current.Delegation, proof.Delegation()) {
		return ErrConflict
	}
	if !proof.Valid() {
		return trust.ErrExpired
	}
	return nil
}

func (r *Runtime) CommitFunctionGrant(ctx context.Context, epoch uint64, operationID string,
	expectedSequence uint64, proof release.VerifiedFunction, binding FunctionBinding,
) (uint64, error) {
	if err := binding.Validate(); err != nil {
		return 0, err
	}
	if !proof.Valid() {
		return 0, trust.ErrExpired
	}
	claim := proof.Claim()
	if catalog.OCIRegion(claim.Cell) != binding.Region {
		return 0, release.ErrExpectationMismatch
	}
	grant := FunctionGrant{TenantID: claim.TenantID, FunctionID: claim.FunctionID,
		Sequence: claim.Sequence, EnvelopeSHA256: proof.EnvelopeSHA256(), Binding: binding}
	payload, err := json.Marshal(grant)
	if err != nil {
		return 0, err
	}
	return r.commitMutationVerified(ctx, epoch, MutationFunctionGrant, binding.TaskID, operationID,
		expectedSequence, payload, func(ctx context.Context) error {
			if err := r.VerifyFunctionIntent(ctx, proof); err != nil {
				return err
			}
			prior, err := r.ReadFunctionGrant(ctx, binding.TaskID)
			if errors.Is(err, ErrNotFound) {
				return nil
			}
			if err != nil {
				return err
			}
			if !bytes.Equal(prior.Payload, payload) {
				return ErrConflict
			}
			return nil
		})
}

func (r *Runtime) ReadFunctionGrant(ctx context.Context, taskID string) (LogEntry, error) {
	if !functionSwarmID.MatchString(taskID) {
		return LogEntry{}, errors.New("function grant task ID is invalid")
	}
	return r.ReadHostMutation(ctx, MutationFunctionGrant, taskID)
}

func (r *Reader) ReadFunctionGrant(ctx context.Context, taskID string) (LogEntry, error) {
	if !functionSwarmID.MatchString(taskID) {
		return LogEntry{}, errors.New("function grant task ID is invalid")
	}
	return r.ReadHostMutation(ctx, MutationFunctionGrant, taskID)
}

func DecodeFunctionGrant(entry LogEntry) (FunctionGrant, error) {
	var grant FunctionGrant
	if err := json.Unmarshal(entry.Payload, &grant, json.RejectUnknownMembers(true)); err != nil {
		return grant, err
	}
	if _, err := functionIntentKey(grant.TenantID, grant.FunctionID); err != nil {
		return FunctionGrant{}, err
	}
	if entry.Kind != MutationFunctionGrant || entry.Sequence == 0 || entry.SubjectKey != grant.Binding.TaskID ||
		grant.Sequence == 0 || !validTerminalDigest(grant.EnvelopeSHA256) {
		return FunctionGrant{}, errors.New("function grant control-log identity is invalid")
	}
	return grant, grant.Binding.Validate()
}

func (r *Runtime) VerifyFunctionGrant(ctx context.Context, proof release.VerifiedFunction, binding FunctionBinding) error {
	return verifyFunctionGrant(ctx, r, proof, binding)
}

func (r *Reader) VerifyFunctionGrant(ctx context.Context, proof release.VerifiedFunction, binding FunctionBinding) error {
	return verifyFunctionGrant(ctx, r, proof, binding)
}

type functionGrantReader interface {
	functionIntentReader
	ReadFunctionGrant(context.Context, string) (LogEntry, error)
}

func verifyFunctionGrant(ctx context.Context, reader functionGrantReader, proof release.VerifiedFunction, binding FunctionBinding) error {
	if err := binding.Validate(); err != nil {
		return err
	}
	entry, err := reader.ReadFunctionGrant(ctx, binding.TaskID)
	if err != nil {
		return err
	}
	grant, err := DecodeFunctionGrant(entry)
	if err != nil {
		return err
	}
	claim := proof.Claim()
	if grant.TenantID != claim.TenantID || grant.FunctionID != claim.FunctionID || grant.Sequence != claim.Sequence ||
		grant.EnvelopeSHA256 != proof.EnvelopeSHA256() || grant.Binding != binding {
		return ErrConflict
	}
	return verifyFunctionIntent(ctx, reader, proof)
}

authority_start.text:
func Start(ctx context.Context, js jetstream.JetStream, config Config) (*Runtime, error) {
	if js == nil {
		return nil, errors.New("JetStream is required")
	}
	config = config.withDefaults()
	if err := config.validate(); err != nil {
		return nil, err
	}
	if config.ClockCheck != nil && config.ClockCheck() != nil {
		return nil, ErrClockUnhealthy
	}
	logger := config.Logger
	if logger == nil {
		logger = slog.Default()
	}
	stream, err := openControlStream(ctx, js, config.Replicas)
	if err != nil {
		return nil, fmt.Errorf("open authority control log: %w", err)
	}
	readCtx, readCancel := context.WithTimeout(ctx, authorityAPITimeout)
	readStream, err := js.Stream(readCtx, ControlStreamName)
	readCancel()
	if err != nil {
		return nil, fmt.Errorf("open authority read handle: %w", err)
	}
	infoCtx, infoCancel := context.WithTimeout(ctx, authorityAPITimeout)
	readInfo, err := readStream.Info(infoCtx)
	infoCancel()
	if err != nil {
		return nil, fmt.Errorf("inspect authority read handle: %w", err)
	}
	if err := verifyControlStreamConfig(readInfo.Config, config.Replicas); err != nil {
		return nil, fmt.Errorf("validate authority read handle: %w", err)
	}
	loopCtx, cancel := context.WithCancel(ctx)
	runtime := &Runtime{
		js:          js,
		publisher:   js,
		stream:      stream,
		readStream:  readStream,
		config:      config,
		leaseSub:    fmt.Sprintf("%s.%s.lease", controlSubjectRoot, config.Scope),
		ownerID:     entityid.New(),
		logger:      logger,
		diagnostics: authorityDiagnosticQueue,
		diagTimes:   make(map[string]time.Time),
		cancel:      cancel,
		done:        make(chan struct{}),
	}
	runtime.publishSnapshot(Snapshot{Scope: config.Scope, DeploymentID: config.DeploymentID, CandidateID: config.CandidateID, OwnerID: runtime.ownerID, Reason: "not-observed"})
	runtime.logSnapshotTransition()
	var observeErr error
	for attempt := range startupReconcileAttempts {
		observeErr = runtime.reconcileWithRetry(loopCtx)
		runtime.logSnapshotTransition()
		if observeErr != nil && loopCtx.Err() != nil {
			observeErr = loopCtx.Err()
			break
		}
		if observeErr == nil || !retryableStartupReconcileError(loopCtx, observeErr) || attempt+1 == startupReconcileAttempts {
			break
		}
		timer := time.NewTimer(startupReconcileDelay(attempt, observeErr))
		select {
		case <-loopCtx.Done():
			observeErr = loopCtx.Err()
			timer.Stop()
		case <-timer.C:
		}
	}
	if observeErr != nil {
		cancel()
		close(runtime.done)
		return nil, fmt.Errorf("observe authority lease: %w", observeErr)
	}
	go runtime.run(loopCtx)
	return runtime, nil
}

authority_log.text:
func (r *Runtime) CommitHostMutationVerified(
	ctx context.Context,
	expectedEpoch uint64,
	kind HostMutationKind,
	subjectKey string,
	operationID string,
	expectedSubjectSequence uint64,
	payload []byte,
	verify func(context.Context) error,
) (uint64, error) {
	if err := validateHostMutation(kind, subjectKey, operationID, payload); err != nil {
		return 0, err
	}
	if verify == nil {
		return 0, errors.New("verified host mutation requires a verifier")
	}
	return r.commitMutationVerified(ctx, expectedEpoch, kind, subjectKey, operationID,
		expectedSubjectSequence, payload, verify)
}

func (r *Runtime) commitMutation(
	ctx context.Context,
	expectedEpoch uint64,
	kind HostMutationKind,
	subjectKey string,
	operationID string,
	expectedSubjectSequence uint64,
	payload []byte,
) (uint64, error) {
	return r.commitMutationVerified(ctx, expectedEpoch, kind, subjectKey, operationID,
		expectedSubjectSequence, payload, nil)
}

func (r *Runtime) commitMutationVerified(
	ctx context.Context,
	expectedEpoch uint64,
	kind HostMutationKind,
	subjectKey string,
	operationID string,
	expectedSubjectSequence uint64,
	payload []byte,
	verify func(context.Context) error,
) (uint64, error) {
	if r == nil {
		return 0, ErrNotLeader
	}
	if r.checkClock() != nil {
		return 0, ErrClockUnhealthy
	}
	if err := validateMutation(kind, subjectKey, operationID, payload); err != nil {
		return 0, err
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	current := r.Current()
	if !current.CanMutate() || current.Scope != r.config.Scope || current.DeploymentID != r.config.DeploymentID || current.CandidateID != r.config.CandidateID || current.OwnerID != r.ownerID {
		return 0, ErrNotLeader
	}
	if expectedEpoch == 0 || current.Epoch != expectedEpoch {
		return 0, ErrFenced
	}

	subject := mutationSubject(r.config.Scope, kind, subjectKey)
	for range 8 {
		info, err := r.stream.Info(ctx)
		if err != nil {
			return 0, fmt.Errorf("read control log sequence: %w", err)
		}
		if err := verifyControlStreamConfig(info.Config, r.config.Replicas); err != nil {
			return 0, fmt.Errorf("validate control log consistency: %w", err)
		}
		leaseEntry, err := r.stream.GetLastMsgForSubject(ctx, r.leaseSub)
		if err != nil {
			r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, Reason: "lease-unreadable"})
			return 0, err
		}
		if leaseEntry.Sequence > info.State.LastSeq {
			continue
		}
		lease, err := decodeLease(leaseEntry.Data)
		if err != nil {
			r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, Reason: "lease-corrupt"})
			return 0, ErrLeaseCorrupt
		}
		if lease.Scope != r.config.Scope || lease.DeploymentID != r.config.DeploymentID || lease.CandidateID != r.config.CandidateID || lease.OwnerID != r.ownerID || lease.Epoch != expectedEpoch || lease.Released ||
			!time.Now().Before(leaseEntry.Time.Add(time.Duration(lease.LeaseDuration))) {
			r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: lease.DeploymentID, CandidateID: lease.CandidateID, Epoch: lease.Epoch, Revision: leaseEntry.Sequence, ObservedAt: time.Now(), Reason: "lease-fenced"})
			return 0, ErrFenced
		}

		existing, err := r.stream.GetLastMsgForSubject(ctx, subject)
		if errors.Is(err, jetstream.ErrMsgNotFound) {
			existing = nil
		} else if err != nil {
			return 0, fmt.Errorf("read prior host mutation: %w", err)
		}
		if existing != nil && existing.Sequence > info.State.LastSeq {
			continue
		}
		if existing != nil {
			prior, decodeErr := decodeControlRecord(existing.Data)
			if decodeErr != nil {
				return 0, fmt.Errorf("decode prior host mutation: %w", decodeErr)
			}
			if prior.OperationID == operationID {
				if prior.Kind == kind && prior.SubjectKey == subjectKey && prior.Epoch == expectedEpoch && bytes.Equal(prior.Payload, payload) {
					return existing.Sequence, nil
				}
				return 0, ErrOperationConflict
			}
			if existing.Sequence != expectedSubjectSequence {
				return 0, ErrConflict
			}
		} else if expectedSubjectSequence != 0 {
			return 0, ErrConflict
		}
		if verify != nil {
			if err := r.verify(ctx, expectedEpoch, leaseEntry.Sequence, info.State.LastSeq,
				subject, operationID, leaseEntry.Time.Add(time.Duration(lease.LeaseDuration)), verify); err != nil {
				return 0, err
			}
			if !time.Now().Before(leaseEntry.Time.Add(time.Duration(lease.LeaseDuration))) {
				return 0, ErrFenced
			}
		}

		record := controlRecord{
			Version: 1, Kind: kind, Scope: r.config.Scope, SubjectKey: subjectKey,
			OperationID: operationID, Epoch: expectedEpoch, Payload: bytes.Clone(payload),
		}
		data, err := json.Marshal(record)
		if err != nil {
			return 0, err
		}
		msg := controlMessage(subject, string(kind), operationID, data)
		ack, err := r.js.PublishMsg(ctx, msg,
			jetstream.WithExpectLastSequence(info.State.LastSeq),
			jetstream.WithExpectLastSequenceForSubject(expectedSubjectSequence, subject),
		)
		if err == nil {
			return ack.Sequence, nil
		}
		if isSequenceConflict(err) {
			latest, readErr := r.stream.GetLastMsgForSubject(ctx, subject)
			if readErr == nil {
				prior, decodeErr := decodeControlRecord(latest.Data)
				if decodeErr == nil && prior.OperationID == operationID {
					if prior.Kind == kind && prior.SubjectKey == subjectKey && prior.Epoch == expectedEpoch && bytes.Equal(prior.Payload, payload) {
						return latest.Sequence, nil
					}
					return 0, ErrOperationConflict
				}
				if latest.Sequence != expectedSubjectSequence {
					return 0, ErrConflict
				}
			}
			continue
		}
		return r.resolveUnknownMutation(ctx, subject, kind, subjectKey, operationID, expectedEpoch, payload, err)
	}
	return 0, ErrConflict
}

// ReadHostMutation reads the current committed host record.
func (r *Runtime) ReadHostMutation(ctx context.Context, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	if r == nil {
		return LogEntry{}, ErrNotFound
	}
	if err := validateMutationKey(kind, subjectKey); err != nil {
		return LogEntry{}, err
	}
	r.readMu.Lock()
	defer r.readMu.Unlock()
	return readMutation(ctx, r.readStream, r.config.Scope, kind, subjectKey)
}

func readMutation(ctx context.Context, stream jetstream.Stream, scope string, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	subject := mutationSubject(scope, kind, subjectKey)
	entry, err := stream.GetLastMsgForSubject(ctx, subject)
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return LogEntry{}, ErrNotFound
	}
	if err != nil {
		return LogEntry{}, err
	}
	record, err := decodeControlRecord(entry.Data)
	if err != nil || record.Scope != scope || record.Kind != kind || record.SubjectKey != subjectKey || record.Epoch == 0 {
		return LogEntry{}, errors.New("host control log entry is invalid")
	}
	return LogEntry{
		Kind: record.Kind, SubjectKey: record.SubjectKey, OperationID: record.OperationID,
		Epoch: record.Epoch, Sequence: entry.Sequence, CreatedAt: entry.Time, Payload: bytes.Clone(record.Payload),
	}, nil
}

sampler.text:
func NewSampler(config SamplerConfig) *Sampler {
	if config.CgroupMount == "" {
		config.CgroupMount = "/sys/fs/cgroup"
	}
	if config.ReadSystem == nil {
		config.ReadSystem = observability.ReadSystem
	}
	if config.Now == nil {
		config.Now = time.Now
	}
	return &Sampler{config: config, roles: make(map[string]cpuPoint)}
}

// Sample reads the host once. terrabase carries the latest verified load
// block per TerraBase role; roles without one report none. Unreadable
// sources leave their fields nil instead of failing the report.
func (s *Sampler) Sample(terrabase map[string]memberstatus.Load) Report {
	s.mu.Lock()
	defer s.mu.Unlock()
	now := s.config.Now()
	report := Report{SchemaVersion: SchemaVersion}
	memTotal := uint64(0)
	if view, err := s.config.ReadSystem(s.config.Filesystems); err == nil {
		memTotal = view.MemTotalBytes
		if view.CPUCount > 0 && view.CPUCount <= MaxCPUCores {
			report.Host.CPUCores = view.CPUCount
		}
		if view.MemTotalBytes <= MaxMemoryBytes {
			report.Host.MemoryBytes = view.MemTotalBytes
		}
		busy := view.CPUSeconds.Busy()
		total := busy + view.CPUSeconds.Idle + view.CPUSeconds.IOWait
		if s.hostSeen && total > s.host.total && busy >= s.host.usage {
			report.Host.CPU = ratio(busy-s.host.usage, total-s.host.total)
		}
		s.host, s.hostSeen = cpuPoint{usage: busy, total: total, at: now}, true
		if view.MemTotalBytes > 0 && view.MemAvailBytes <= view.MemTotalBytes {
			report.Host.Memory = ratio(float64(view.MemTotalBytes-view.MemAvailBytes), float64(view.MemTotalBytes))
		}
		if finiteWithin(view.Load1, MaxLoad1) {
			load := view.Load1
			report.Host.Load1 = &load
		}
		if rx, tx := view.NetRxBytes, view.NetTxBytes; rx > 0 && tx > 0 {
			// A counter that went backwards means the interface reset, so
			// that interval has no valid rate.
			if elapsed := now.Sub(s.net.at).Seconds(); s.net.seen && elapsed > 0 && rx >= s.net.rx && tx >= s.net.tx {
				rxBps := float64(rx-s.net.rx) / elapsed
				txBps := float64(tx-s.net.tx) / elapsed
				if finiteWithin(rxBps, MaxNetworkBps) && finiteWithin(txBps, MaxNetworkBps) {
					report.Host.NetworkRxBps, report.Host.NetworkTxBps = &rxBps, &txBps
				}
			}
			s.net = netPoint{rx: rx, tx: tx, at: now, seen: true}
		}
		seen := make(map[string]bool)
		for _, filesystem := range view.Filesystems {
			if len(report.Host.Filesystems) == MaxFilesystems {
				report.Host.FilesystemsIncomplete = true
				break
			}
			if !validFilesystem(filesystem) || seen[filesystem.Role] {
				report.Host.FilesystemsIncomplete = true
				continue
			}
			seen[filesystem.Role] = true
			report.Host.Filesystems = append(report.Host.Filesystems, filesystem)
			used := ratio(float64(filesystem.SizeBytes-filesystem.AvailBytes), float64(filesystem.SizeBytes))
			if report.Host.Disk == nil || *used > *report.Host.Disk {
				report.Host.Disk = used
			}
		}
	} else {
		report.Host.FilesystemsIncomplete = true
	}
	present := make(map[string]struct{}, len(s.config.Roles))
	for _, role := range s.config.Roles {
		if len(report.Roles) == MaxRoles {
			break
		}
		usage, seen := s.sampleCgroup(role, now, memTotal)
		if seen {
			present[role] = struct{}{}
		}
		if load, ok := terrabase[role]; ok && load.Validate() == nil {
			usage.TerraBase = &load
		}
		if usage.CPUCores != nil || usage.MemoryBytes != nil || usage.TerraBase != nil {
			report.Roles = append(report.Roles, usage)
		}
	}
	// A role whose group vanished (stopped workload) restarts its CPU
	// baseline when it comes back, so a restart never reads as a burst.
	s.forgetCgroups(present)
	return report
}

report_validate.text:
func (r Report) Validate() error {
	if r.SchemaVersion != SchemaVersion {
		return fmt.Errorf("%w: schema version %d", ErrInvalidReport, r.SchemaVersion)
	}
	if r.Host.CPUCores < 0 || r.Host.CPUCores > MaxCPUCores || r.Host.MemoryBytes > MaxMemoryBytes {
		return fmt.Errorf("%w: host capacity out of range", ErrInvalidReport)
	}
	for _, value := range []*float64{r.Host.CPU, r.Host.Memory, r.Host.Disk} {
		if value != nil && !fraction(*value) {
			return fmt.Errorf("%w: host utilization out of range", ErrInvalidReport)
		}
	}
	for _, value := range []*float64{r.Host.NetworkRxBps, r.Host.NetworkTxBps} {
		if value != nil && !finiteWithin(*value, MaxNetworkBps) {
			return fmt.Errorf("%w: host network rate out of range", ErrInvalidReport)
		}
	}
	if r.Host.Load1 != nil && !finiteWithin(*r.Host.Load1, MaxLoad1) {
		return fmt.Errorf("%w: host load out of range", ErrInvalidReport)
	}
	if len(r.Host.Filesystems) > MaxFilesystems {
		return fmt.Errorf("%w: more than %d filesystems", ErrInvalidReport, MaxFilesystems)
	}
	filesystems := make(map[string]bool, len(r.Host.Filesystems))
	for _, filesystem := range r.Host.Filesystems {
		if !validFilesystem(filesystem) || filesystems[filesystem.Role] {
			return fmt.Errorf("%w: invalid or repeated filesystem role %q", ErrInvalidReport, filesystem.Role)
		}
		filesystems[filesystem.Role] = true
	}
	if len(r.Roles) > MaxRoles {
		return fmt.Errorf("%w: more than %d roles", ErrInvalidReport, MaxRoles)
	}
	seen := make(map[string]struct{}, len(r.Roles))
	tasks := make(map[string]struct{})
	for _, role := range r.Roles {
		if !roleRE.MatchString(role.Role) {
			return fmt.Errorf("%w: role token", ErrInvalidReport)
		}
		if _, repeated := seen[role.Role]; repeated {
			return fmt.Errorf("%w: repeated role %q", ErrInvalidReport, role.Role)
		}
		seen[role.Role] = struct{}{}
		for _, task := range role.Tasks {
			if !validTaskID(task.TaskID) || !validTaskID(task.ServiceID) || !validTaskID(task.NodeID) ||
				len(task.Fingerprint) != 64 || strings.IndexFunc(task.Fingerprint, func(r rune) bool {
				return !(r >= '0' && r <= '9' || r >= 'a' && r <= 'f')
			}) >= 0 {
				return fmt.Errorf("%w: invalid task identity pin", ErrInvalidReport)
			}
			if _, repeated := tasks[task.TaskID]; repeated {
				return fmt.Errorf("%w: repeated task identity pin", ErrInvalidReport)
			}
			tasks[task.TaskID] = struct{}{}
			if len(tasks) > MaxTasks {
				return fmt.Errorf("%w: more than %d task identity pins", ErrInvalidReport, MaxTasks)
			}
		}
		if role.CPUCores != nil && !finiteWithin(*role.CPUCores, MaxCPUCores) {
			return fmt.Errorf("%w: role %q CPU out of range", ErrInvalidReport, role.Role)
		}
		if role.MemoryBytes != nil && *role.MemoryBytes > MaxMemoryBytes {
			return fmt.Errorf("%w: role %q memory out of range", ErrInvalidReport, role.Role)
		}
		if role.CPULimit != nil && (!finiteWithin(*role.CPULimit, MaxCPUCores) || *role.CPULimit == 0) ||
			role.MemoryLimit != nil && *role.MemoryLimit > MaxMemoryBytes {
			return fmt.Errorf("%w: role limit out of range", ErrInvalidReport)
		}
		if role.TerraBase != nil {
			if err := role.TerraBase.Validate(); err != nil {
				return fmt.Errorf("%w: role %q: %v", ErrInvalidReport, role.Role, err)
			}
		}
		if role.WAN != nil {
			if role.Role != terrabase.Role {
				return fmt.Errorf("%w: WAN observations require the terrabase role", ErrInvalidReport)
			}
			if err := role.WAN.Validate(); err != nil {
				return fmt.Errorf("%w: role %q WAN: %v", ErrInvalidReport, role.Role, err)
			}
		}
	}
	return nil
}

func validTaskID(value string) bool {
	return len(value) > 0 && len(value) <= 64 && strings.IndexFunc(value, func(r rune) bool {
		return !(r >= 'a' && r <= 'z' || r >= '0' && r <= '9')
	}) < 0
}

func validFilesystem(filesystem observability.FilesystemView) bool {
	return protocol.ValidateSubjectToken(filesystem.Role) == nil &&
		len(filesystem.Path) <= 4096 && utf8.ValidString(filesystem.Path) &&
		filepath.IsAbs(filesystem.Path) && filepath.Clean(filesystem.Path) == filesystem.Path &&
		!strings.ContainsFunc(filesystem.Path, unicode.IsControl) &&
		filesystem.SizeBytes > 0 && filesystem.SizeBytes <= MaxFilesystemBytes &&
		filesystem.AvailBytes <= filesystem.FreeBytes && filesystem.FreeBytes <= filesystem.SizeBytes &&
		filesystem.Files <= MaxFilesystemBytes && filesystem.FilesFree <= filesystem.Files
}

func fraction(value float64) bool { return finiteWithin(value, 1) }

func finiteWithin(value, limit float64) bool {
	return !math.IsNaN(value) && !math.IsInf(value, 0) && value >= 0 && value <= limit
}

system_read.text:
func ReadSystem(filesystems []FilesystemRole) (SystemView, error) {
	view, err := readSystem("/proc", filesystems, statFilesystem)
	view.Clock = readClock()
	return view, err
}

func readSystem(procRoot string, filesystems []FilesystemRole,
	stat func(string) (FilesystemView, error),
) (SystemView, error) {
	var view SystemView
	data, err := os.ReadFile(filepath.Join(procRoot, "stat"))
	if err != nil {
		return SystemView{}, err
	}
	if view.CPUSeconds, view.CPUCount, err = parseProcStat(data); err != nil {
		return SystemView{}, err
	}
	data, err = os.ReadFile(filepath.Join(procRoot, "meminfo"))
	if err != nil {
		return SystemView{}, err
	}
	memory, err := parseMeminfo(data)
	if err != nil {
		return SystemView{}, err
	}
	view.MemTotalBytes, view.MemAvailBytes = memory["MemTotal"], memory["MemAvailable"]
	view.SwapTotalBytes, view.SwapFreeBytes = memory["SwapTotal"], memory["SwapFree"]
	if data, err = os.ReadFile(filepath.Join(procRoot, "loadavg")); err == nil {
		view.Load1, view.Load5, view.Load15, _ = parseLoadavg(data)
	}
	if data, err = os.ReadFile(filepath.Join(procRoot, "uptime")); err == nil {
		view.UptimeSeconds, _ = parseUptime(data)
	}
	if data, err = os.ReadFile(filepath.Join(procRoot, "self", "status")); err == nil {
		view.ProcessRSSBytes = parseStatusRSS(data)
	}
	if rx, tx, ok := readNetDev(filepath.Join(procRoot, "net", "dev")); ok {
		view.NetRxBytes, view.NetTxBytes = rx, tx
	}
	for _, resource := range []string{"cpu", "memory", "io"} {
		data, err := os.ReadFile(filepath.Join(procRoot, "pressure", resource))
		if err != nil {
			continue
		}
		if psi, err := parsePressure(data); err == nil {
			if view.Pressure == nil {
				view.Pressure = map[string]PSI{}
			}
			view.Pressure[resource] = psi
		}
	}
	for _, filesystem := range filesystems {
		if filesystem.Role == "" || filesystem.Path == "" {
			continue
		}
		observed, err := stat(filesystem.Path)
		if err != nil {
			observed = FilesystemView{}
		}
		observed.Role, observed.Path = filesystem.Role, filesystem.Path
		view.Filesystems = append(view.Filesystems, observed)
	}
	return view, nil
}

system_stat.text:
func statFilesystem(path string) (FilesystemView, error) {
	var stat unix.Statfs_t
	if err := unix.Statfs(path, &stat); err != nil {
		return FilesystemView{}, err
	}
	blockSize := uint64(stat.Bsize)
	view := FilesystemView{SizeBytes: stat.Blocks * blockSize, AvailBytes: stat.Bavail * blockSize,
		FreeBytes: stat.Bfree * blockSize, Files: stat.Files, FilesFree: stat.Ffree}
	var info unix.Stat_t
	if err := unix.Stat(path, &info); err == nil {
		view.Device = uint64(info.Dev) // Dev is narrower on some architectures.
	}
	return view, nil
}
